					`Imported into CodePi storage: ${list || "nothing new"}.`,
				);
			} catch (err) {
				vscode.window.showErrorMessage(
					`Failed to import pi config: ${err instanceof Error ? err.message : String(err)}`,
				);
			}
		}
	}
